-- Тема 21. Основы сетей: 48 практических вопросов; вне экзамена, пояснения к каждому варианту.
-- Источник: scripts/questions/149_networks.js
-- Повторный запуск безопасен; несовпадение ранее добавленного вопроса отменяет пакет.


BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE question_seed (
    category_id integer NOT NULL,
    question_text text NOT NULL UNIQUE,
    options jsonb NOT NULL,
    correct_answer text NOT NULL,
    explanation text NOT NULL,
    option_notes jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO question_seed
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'На Linux есть eth0 и eth1. Что можно определить по этим именам без просмотра адресов и маршрутов?', '{"A":"eth1 служит резервной копией eth0","B":"Это два разных сетевых интерфейса","C":"eth1 используется для репликации","D":"eth0 подключён к публичной сети"}'::jsonb, 'B', 'Интерфейс бывает физическим или виртуальным. Чтобы понять его назначение, смотрят адреса, маршруты и конфигурацию.', '{"A":"Резервирование требует отдельной настройки, например bonding.","B":"Имена обозначают разные интерфейсы в данном сетевом пространстве.","C":"Номер не задаёт назначение трафика или службы.","D":"Назначение интерфейса определяется конфигурацией, а не номером."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В ip address внутри eth0 видны 192.0.2.10/24 с меткой eth0 и 192.0.2.20/24 с меткой eth0:0. Что настроено?', '{"A":"Один адрес и его шлюз по умолчанию","B":"Два маршрута для разных DNS-серверов","C":"Два интерфейса с отдельными кабелями","D":"Два IPv4-адреса на одном интерфейсе"}'::jsonb, 'D', 'eth0:0 — традиционная метка дополнительного IPv4-адреса. Это отличается от отдельного интерфейса eth1.', '{"A":"Оба значения перечислены как локальные адреса; шлюз ищут в маршрутах.","B":"ip address показывает адреса, а не назначения DNS-маршрутов.","C":"Метка адреса не создаёт отдельную физическую или виртуальную карту.","D":"Метка eth0:0 относится к дополнительному адресу того же eth0."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'После установки Linux сетевая карта называется enp2s0, а не eth0. Как проверить, какой у неё IP-адрес?', '{"A":"Найти DNS-сервер в /etc/resolv.conf","B":"Прочитать маршрут через ip route get","C":"Выполнить ip -br address","D":"Посмотреть порт службы через ss -ltn"}'::jsonb, 'C', 'Современные имена могут отражать расположение устройства. Имя enp2s0 не говорит, публичная это сеть или внутренняя.', '{"A":"Адрес резолвера не является адресом сетевой карты.","B":"Для route get нужен адрес назначения; это не обзор адресов карт.","C":"Команда перечисляет интерфейсы и назначенные им адреса.","D":"ss показывает сокеты, а не полный список адресов интерфейсов."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'На ноутбуке запущен SSH-клиент. Куда он пытается подключиться по команде ssh 127.0.0.1?', '{"A":"К службе SSH на самом ноутбуке","B":"К первой машине из списка known_hosts","C":"К шлюзу локальной сети ноутбука","D":"К серверу из последнего SSH-сеанса"}'::jsonb, 'A', '127.0.0.1 — IPv4 loopback. Удалённый сервер имеет собственный loopback, доступный из процессов на нём.', '{"A":"Loopback относится к машине, где работает клиент.","B":"known_hosts хранит доверенные ключи серверов, а не цель по умолчанию.","C":"Адрес шлюза выбирают из таблицы маршрутов, это не 127.0.0.1.","D":"Предыдущее подключение не меняет значение loopback-адреса."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Приложение работает в Docker-контейнере с отдельным сетевым пространством. Оно обращается к 127.0.0.1:5432. Куда идёт соединение?', '{"A":"К соседнему контейнеру с базой данных","B":"К первому опубликованному порту Docker","C":"К порту 5432 внутри этого контейнера","D":"К PostgreSQL на физическом сервере"}'::jsonb, 'C', 'Это объясняет частую ошибку: localhost приложения в контейнере и localhost базы на хосте находятся в разных сетевых пространствах.', '{"A":"Соседний контейнер нужно адресовать по доступному имени или адресу.","B":"Публикация портов не перенаправляет loopback исходящих соединений.","C":"В отдельном сетевом пространстве у контейнера свой loopback.","D":"Loopback контейнера не указывает на хост автоматически."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Хост отправляет IPv4-пакет в удалённую подсеть через Ethernet-шлюз. Какая пара адресов назначения используется при отправке первого кадра? NAT и туннелей нет.', '{"A":"IP удалённого хоста, MAC шлюза","B":"IP шлюза, MAC удалённого хоста","C":"IP удалённого хоста, MAC DNS-сервера","D":"IP шлюза, MAC отправляющего хоста"}'::jsonb, 'A', 'IP-маршрутизация выбирает следующий переход, а Ethernet доставляет кадр в пределах текущего канала. MAC-адреса меняются между переходами.', '{"A":"IP указывает конечный узел, а Ethernet-кадр доставляется ближайшему шлюзу.","B":"MAC удалённого хоста из другой сети не нужен для первого перехода.","C":"DNS разрешает имя, но не становится следующим сетевым узлом.","D":"MAC отправителя не может заменить адрес назначения кадра."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'На интерфейсе задан адрес 192.0.2.10/24. Какая маска соответствует /24?', '{"A":"255.255.0.0","B":"255.255.255.0","C":"255.255.255.128","D":"255.255.255.255"}'::jsonb, 'B', 'Длина префикса показывает, сколько старших битов относится к сети. Для /24 остаётся 8 битов адресной части узла.', '{"A":"Эта маска содержит 16 единичных битов, то есть /16.","B":"Первые 24 бита маски равны единице.","C":"Эта маска соответствует /25, а не /24.","D":"Это /32 — префикс одного IPv4-адреса."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'У сервера IPv4-адрес 192.0.2.70/26. Каков адрес этой подсети?', '{"A":"192.0.2.70","B":"192.0.2.0","C":"192.0.2.64","D":"192.0.2.128"}'::jsonb, 'C', 'У /26 маска 255.255.255.192. Подсеть 192.0.2.64/26 содержит адреса от .64 до .127.', '{"A":"Это заданный адрес узла, а не начало блока из 64 адресов.","B":"Этот адрес начал бы первую /26, но 70 находится в следующем блоке.","C":"Подсети /26 в этом /24 начинаются с 0, 64, 128 и 192.","D":"Это начало следующей /26; адрес 70 в неё не входит."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Какой широковещательный адрес у обычной IPv4-подсети 192.0.2.64/26?', '{"A":"192.0.2.255","B":"192.0.2.126","C":"192.0.2.64","D":"192.0.2.127"}'::jsonb, 'D', 'Для обычной broadcast-подсети адрес с нулевой адресной частью обозначает сеть, а со всеми единицами — broadcast. Правила /31 отличаются.', '{"A":"Это broadcast для 192.0.2.0/24, но не для выбранной /26.","B":"Это последний обычный адрес узла в данной подсети.","C":"Это адрес сети, а не широковещательный адрес.","D":"Это последний адрес блока .64–.127."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В маршрутах есть запись 203.0.113.9/32 via 192.0.2.1. Для каких адресов назначения подходит её префикс?', '{"A":"Для диапазона 203.0.113.1–254","B":"Для подсети 203.0.113.0/24","C":"Для адресов из сети 192.0.2.0/24","D":"Для адреса 203.0.113.9"}'::jsonb, 'D', 'Маршрут /32 называют host route. Его длина делает его более специфичным, чем подходящие /24 или default.', '{"A":"Префикс /32 не охватывает весь диапазон узлов /24.","B":"В /24 зафиксированы 24 бита, а здесь указано 32.","C":"192.0.2.1 здесь следующий переход, а не префикс назначения.","D":"Все 32 бита префикса зафиксированы: это маршрут к одному IPv4-адресу."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Какие из перечисленных IPv4-адресов входят в частные диапазоны RFC 1918?', '{"A":"192.168.2.3","B":"172.20.1.5","C":"172.32.1.5","D":"10.2.3.4"}'::jsonb, 'ABD', 'Частный адрес не маршрутизируется глобально как публичный адрес. Для выхода через публичный адрес часто используют NAT; доступ через частные сети и VPN тоже возможен.', '{"A":"Входит в частный диапазон 192.168.0.0/16.","B":"Входит в 172.16.0.0/12: второй октет от 16 до 31.","C":"Диапазон 172.16.0.0/12 заканчивается на 172.31.255.255.","D":"Входит в частный диапазон 10.0.0.0/8."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В IPv6-маршруте шлюз записан как fe80::1 dev eth0. Почему для такого шлюза существенен интерфейс?', '{"A":"Префикс fe80::1 задаёт TCP-порт","B":"Адрес fe80::1 является IPv4-маской","C":"Link-local адрес имеет область канала","D":"Имя eth0 заменяет адрес DNS-сервера"}'::jsonb, 'C', 'Link-local IPv6-адреса относятся к fe80::/10 и не пересылаются маршрутизаторами за пределы канала. Для их однозначного использования нужен сетевой интерфейс.', '{"A":"IPv6-адрес и транспортный порт — разные части адресации.","B":"Это IPv6 link-local адрес, он не задаёт маску IPv4.","C":"Одинаковое fe80::1 может существовать на разных каналах.","D":"dev выбирает интерфейс следующего перехода, а не резолвер."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Какой адрес используют для подключения к IPv6 loopback на той же машине?', '{"A":"fe80::1","B":"::1","C":"2001:db8::1","D":"::"}'::jsonb, 'B', 'Служба может слушать IPv4 loopback, IPv6 loopback или оба. Поэтому localhost и явный 127.0.0.1 иногда дают разные результаты.', '{"A":"Это link-local адрес на канале, а не IPv6 loopback.","B":"Это loopback IPv6, аналогичный по назначению 127.0.0.1 в IPv4.","C":"Это адрес из диапазона примеров документации, а не loopback.","D":"Это неопределённый IPv6-адрес, часто используемый при привязке слушателя."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Как прочитать маршрут «default via 192.0.2.1 dev eth0»?', '{"A":"DNS-запросы — через сервер 192.0.2.1 по eth0","B":"Без более точного маршрута — через 192.0.2.1","C":"Входящие пакеты — перенаправить на адрес eth0","D":"Любой трафик — мимо остальных записей таблицы"}'::jsonb, 'B', 'Default для IPv4 соответствует префиксу 0.0.0.0/0. Адрес после via — следующий переход, а dev указывает интерфейс.', '{"A":"Эта запись не ограничена протоколом DNS и не задаёт резолвер.","B":"Default используется, когда в выбранной таблице нет более специфичного подходящего маршрута.","C":"Маршрут задаёт выбор пути, а не перенаправление входящих соединений.","D":"Более длинный подходящий префикс имеет преимущество перед default."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В одной таблице IPv4-маршрутов есть default через eth0 с metric 10 и 10.5.0.0/16 через eth1 с metric 500. Других правил нет. Куда уйдёт пакет для 10.5.2.3?', '{"A":"Поровну через eth0 и eth1","B":"Пакет будет отброшен ядром","C":"По маршруту /16 через eth1","D":"По default через eth0"}'::jsonb, 'C', 'При обычном выборе маршрута в одной таблице длина префикса важнее metric. Policy routing может сначала выбрать другую таблицу.', '{"A":"Для балансировки нужны условия multipath, а не просто две разные записи.","B":"Подходящий /16 есть, разница metric не делает таблицу ошибочной.","C":"Сначала выбирается самый длинный подходящий префикс.","D":"Меньшая metric у default не отменяет более специфичный /16."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В одной таблице есть два обычных unicast-маршрута 10.5.0.0/16: через eth0 с metric 100 и через eth1 с metric 200. Других ограничений и multipath нет. Какой предпочтительнее?', '{"A":"Через последний изменённый интерфейс","B":"Через eth1 с metric 200","C":"Через eth0 с metric 100","D":"Через первый интерфейс по алфавиту"}'::jsonb, 'C', 'Сравнивать metric нужно после выбора подходящих префиксов и в контексте нужной таблицы маршрутизации.', '{"A":"Время последней настройки карты не заменяет metric.","B":"Большая metric не повышает приоритет обычного маршрута.","C":"При равном префиксе меньшая metric задаёт предпочтительный маршрут.","D":"Приоритет задаётся параметрами маршрута, а не сортировкой имён."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Как посмотреть решение Linux о маршруте к 203.0.113.10, не отправляя проверочный пакет этому узлу?', '{"A":"ip route get 203.0.113.10","B":"ping -c 1 203.0.113.10","C":"ip address show 203.0.113.10","D":"ss -ltn dst 203.0.113.10"}'::jsonb, 'A', 'В выводе route get полезны dev, via и src. Для сложной схемы можно дополнительно указать from и проверить policy rules.', '{"A":"Команда выполняет поиск маршрута и показывает результат.","B":"ping отправляет ICMP-пакет, а не просто читает решение маршрутизации.","C":"ip address показывает локальные адреса и не так запрашивает путь к удалённому узлу.","D":"ss работает с сокетами, а не выбирает будущий маршрут."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'ip route get 203.0.113.10 выводит «via 192.0.2.1 dev eth0 src 192.0.2.10». Что означает src при обычном соединении без явной привязки клиента?', '{"A":"IP-адрес удалённого сервера","B":"Выбранный исходный IP-адрес","C":"MAC-адрес выбранного шлюза","D":"Адрес DNS-сервера приложения"}'::jsonb, 'B', 'Наличие двух локальных IP не означает, что каждое приложение использует дополнительный. Привязка сокета и policy routing могут изменить выбор источника.', '{"A":"Удалённый адрес здесь 203.0.113.10.","B":"Ядро показывает адрес источника для данного поиска маршрута.","C":"192.0.2.10 — IPv4-адрес, а MAC имеет другой формат.","D":"Маршрут не сообщает, каким резолвером воспользуется приложение."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Есть интерфейс 192.0.2.10/24. Администратор задаёт шлюз 198.51.100.1; специальных маршрутов к нему и onlink нет. Почему ядро может отклонить такой маршрут?', '{"A":"Не подтверждена достижимость следующего перехода","B":"Перед настройкой маршрута надо открыть порт 5432","C":"Следующий переход должен совпадать с адресом хоста","D":"Для шлюза обязательно нужна запись DNS типа AAAA"}'::jsonb, 'A', 'Провайдер может использовать специальные схемы с onlink. Их задают по его инструкции, а не считают любой внешний адрес готовым шлюзом.', '{"A":"Шлюз вне подключённой подсети требует подходящего способа достижения.","B":"Порт приложения не определяет допустимость следующего перехода.","C":"Шлюз обычно является другим узлом, а не адресом самого отправителя.","D":"IPv4 next hop может быть задан численно без IPv6 и DNS."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'У eth0 и адреса с меткой eth0:0 прописан одинаковый gateway без разных metric и таблиц. Первый ifup добавил default, второй получил «RTNETLINK answers: File exists». Что исправить в этой схеме?', '{"A":"Создать ещё один идентичный маршрут в той же таблице","B":"Убрать повторное создание default","C":"Удалить дополнительный IP-адрес с интерфейса","D":"Заменить маску обоих адресов на /32 без маршрутов"}'::jsonb, 'B', 'Сначала проверяют фактические адреса и маршруты: после частичного ifup адрес уже может работать, хотя служба находится в failed.', '{"A":"Ещё одна попытка добавить ту же запись не устраняет конфликт.","B":"Для двух адресов в одной подсети достаточно одного такого маршрута.","C":"Дополнительный адрес допустим; ошибка относится к повторному маршруту.","D":"Произвольная смена маски может разрушить достижимость шлюза."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'На хосте нет default, но есть подключённый маршрут 192.0.2.0/24 через eth0. Policy rules, NAT и другие таблицы не используются. Какой узел достижим по имеющемуся IPv4-маршруту?', '{"A":"Любой адрес через IPv4 loopback","B":"Любой узел частной сети 10.0.0.0/8","C":"Сосед 192.0.2.25 в этой подсети","D":"Любой публичный сервер через DNS"}'::jsonb, 'C', 'Достижимость по маршруту ещё не гарантирует ответ: сосед должен существовать и пропускать трафик. Default нужен для направлений без отдельного маршрута.', '{"A":"Loopback не является маршрутизатором к произвольным удалённым сетям.","B":"Для сети 10.0.0.0/8 в условии нет маршрута.","C":"Для него подходит подключённый маршрут /24.","D":"Разрешение имени не создаёт отсутствующий маршрут."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В /etc/hosts задано имя db.internal. Приложение использует системный NSS-резолвер glibc. Какая команда проверит разрешение имени с учётом настроенного NSS?', '{"A":"dig db.internal A","B":"ss -ltnp db.internal","C":"ip route get db.internal","D":"getent ahosts db.internal"}'::jsonb, 'D', 'Если dig и приложение дают разные результаты, нужно учитывать /etc/hosts, NSS, семейство адресов и собственный резолвер приложения.', '{"A":"dig проверяет DNS, но не воспроизводит весь порядок NSS и /etc/hosts.","B":"Просмотр слушающих сокетов не является проверкой NSS.","C":"Это поиск маршрута; он не заменяет просмотр результатов NSS по имени.","D":"getent использует системные базы NSS, включая настроенный источник hosts."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Для одного имени есть DNS-записи A и AAAA. Что они содержат?', '{"A":"A — имя пользователя, AAAA — имя базы","B":"A — TCP-порт, AAAA — UDP-порт","C":"A — основной шлюз, AAAA — резервный шлюз","D":"A — IPv4, AAAA — IPv6"}'::jsonb, 'D', 'Клиент может выбрать IPv4 или IPv6. Успех подключения к A-записи не доказывает работоспособность пути к AAAA-записи.', '{"A":"Эти записи не описывают параметры роли и базы PostgreSQL.","B":"Адресные записи не задают номера транспортных портов.","C":"DNS-адреса сервера не настраивают таблицу маршрутов клиента.","D":"Это два типа адресных DNS-записей."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Имя db.example.test успешно разрешилось в IP. Доказывает ли это, что PostgreSQL на порту 5432 доступен?', '{"A":"Да, DNS проверяет доступность порта базы","B":"Нет, DNS предназначен для HTTP-серверов","C":"Да, если DNS вернул несколько IP-адресов","D":"Нет, TCP и PostgreSQL проверяют отдельно"}'::jsonb, 'D', 'Диагностику разделяют на разрешение имени, маршрут, TCP, протокол базы, аутентификацию и выполнение запроса.', '{"A":"Адресная DNS-запись не выполняет TCP-подключение к PostgreSQL.","B":"DNS используется множеством приложений, включая клиенты баз данных.","C":"Количество адресов не подтверждает доступность ни одного сервиса.","D":"Разрешение имени даёт адрес, а не результат соединения или SQL-запроса."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'IP в DNS изменили. У рекурсивного резолвера ещё есть старая запись с неистёкшим TTL. Что может получить клиент, использующий этот резолвер?', '{"A":"Номер порта вместо прежнего IP-адреса","B":"Адрес шлюза вместо прежнего адреса сервера","C":"Новый адрес сразу после изменения зоны","D":"Старый адрес из действующего кэша"}'::jsonb, 'D', 'При смене адреса учитывают TTL ранее выданных записей и возможное дополнительное кэширование приложением.', '{"A":"Истечение или сохранение TTL не меняет тип A-записи на номер порта.","B":"TTL DNS не подменяет адрес записи сетевым шлюзом.","C":"Клиент может обращаться к резолверу с ещё пригодной кэшированной записью.","D":"Обновление авторитетного DNS не заставляет все кэши немедленно исчезнуть."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'psql сообщает «could not translate host name». На каком этапе начинать диагностику?', '{"A":"С изменения режима WAL на сервере базы","B":"С очистки зависших транзакций на сервере","C":"С проверки имени и его разрешения","D":"С проверки синтаксиса SELECT-запроса"}'::jsonb, 'C', 'Проверяют опечатку, настройки резолвера и доступные адреса. Не начинают с изменения серверной аутентификации.', '{"A":"Режим WAL не отвечает за разрешение имени клиентом.","B":"По этому сообщению нет признака, что клиент вообще достиг сервера.","C":"Клиент ещё не получил пригодный адрес сервера для подключения.","D":"Ошибка произошла раньше установления соединения и отправки SQL."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Какие утверждения о TCP и UDP верны?', '{"A":"TCP предоставляет упорядоченный поток байтов","B":"TCP сохраняет границы каждого write приложения","C":"UDP передаёт отдельные датаграммы","D":"UDP сам повторяет все потерянные датаграммы"}'::jsonb, 'AC', 'Успех транспорта не означает успех прикладной операции. Например, установленный TCP не подтверждает корректность SQL-запроса.', '{"A":"TCP скрывает границы отдельных сегментов от приложения.","B":"Один write не обязан соответствовать одному read на другом конце.","C":"Получатель видит границы сообщений UDP.","D":"Повторы при необходимости реализует приложение или протокол поверх UDP."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Как посмотреть слушающие TCP-порты с числовыми адресами и, при достаточных правах, именами процессов?', '{"A":"ip -br address","B":"ss -lunp","C":"ip route show","D":"ss -ltnp"}'::jsonb, 'D', 'Без достаточных прав часть сведений о чужих процессах может отсутствовать. Числовой вывод не зависит от сопоставления портов именам служб.', '{"A":"Команда показывает адреса интерфейсов, а не слушающие TCP-сокеты.","B":"Здесь u выбирает UDP, а задача требует TCP.","C":"Таблица маршрутов не содержит список процессов, слушающих TCP.","D":"l — слушатели, t — TCP, n — числовой вывод, p — процессы."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'PostgreSQL слушает 127.0.0.1:5432. Клиент с другой машины обращается к публичному IP этого сервера. Достаточно ли такого слушателя для подключения?', '{"A":"Да, если клиент указал тот же порт 5432","B":"Да, если pg_hba.conf разрешает IP клиента","C":"Нет, он привязан к IPv4 loopback","D":"Да, если имя сервера разрешилось через DNS"}'::jsonb, 'C', 'Нужно проверять адрес прослушивания, сетевой доступ и аутентификацию. Не следует автоматически открывать базу всем адресам.', '{"A":"Совпадения порта недостаточно: важен адрес привязки сокета.","B":"Правило HBA не создаёт слушатель на публичном адресе.","C":"Соединение на публичный адрес не принимается слушателем, привязанным к 127.0.0.1.","D":"DNS не расширяет адреса, на которых слушает процесс."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'ss показывает 0.0.0.0:5432 в LISTEN. Что можно заключить из этой строки?', '{"A":"Подключение из интернета уже разрешено firewall","B":"Есть слушатель на всех локальных IPv4-адресах","C":"Сервер уже разрешил вход любой роли PostgreSQL","D":"Слушатель принимает IPv6 на любом адресе хоста"}'::jsonb, 'B', '0.0.0.0 — адрес привязки слушателя, а не адрес сервера, который нужно вводить на удалённом клиенте.', '{"A":"Прослушивание не подтверждает правила firewall и доступность сетевого пути.","B":"0.0.0.0 при bind означает неопределённый IPv4-адрес.","C":"Правила аутентификации не видны из факта LISTEN.","D":"Эта строка относится к IPv4; IPv6 нужно проверять отдельно."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'ss показывает слушатель [::]:5432. Можно ли по одной этой строке гарантировать приём IPv4-подключений?', '{"A":"Нет, нужно проверить режим сокета и IPv4 отдельно","B":"Нет, порт 5432 зарезервирован для IPv4","C":"Да, IPv6-слушатель автоматически заменяет IPv4","D":"Да, если в DNS присутствует запись типа A"}'::jsonb, 'A', 'Проверяют ss для обоих семейств и соединения к конкретным адресам. Нельзя переносить успех IPv6 на IPv4 без проверки.', '{"A":"Приём IPv4 через IPv6-сокет зависит от IPV6_V6ONLY и конфигурации.","B":"Номер порта TCP может использоваться в обоих семействах адресов.","C":"Поведение dual stack зависит от настроек, гарантии по одной строке нет.","D":"DNS-запись не меняет режим IPv6-сокета."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'psql без -h сообщает, что Unix-сокет /var/run/postgresql/.s.PGSQL.5432 не найден. Что сначала проверить?', '{"A":"Работу кластера, порт и каталог сокетов","B":"Доступность публичного маршрута через шлюз","C":"Значение TTL DNS-записи удалённой базы","D":"Проверку TCP-порта вместо локального сокета"}'::jsonb, 'A', 'Кластер может быть остановлен, работать на другом порту или создавать сокет в другом каталоге. Проверяют конкретный экземпляр PostgreSQL.', '{"A":"Ожидаемый локальный Unix-сокет отсутствует; это ещё не результат TCP-проверки.","B":"Unix-сокет между локальными процессами не проходит через шлюз.","C":"В сообщении указан путь локального Unix-сокета, а не DNS-имя.","D":"Работающий TCP-порт не подтверждает наличие Unix-сокета в ожидаемом каталоге."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Подключение TCP к IP и порту быстро завершилось «Connection refused». Как корректно трактовать результат?', '{"A":"SQL-запрос завершился по statement_timeout","B":"Соединение активно отклонено; проверить слушатель и reject","C":"Пароль роли проверен и признан неправильным","D":"DNS не смог преобразовать имя сервера в адрес"}'::jsonb, 'B', 'Быстрый отказ не равен зависанию и не доказывает единственную причину. Сопоставляют адрес/порт клиента со слушателем и правилами доступа.', '{"A":"SQL ещё не мог выполняться: соединение не было установлено.","B":"Причиной может быть отсутствие слушателя или явный отказ сетевого фильтра.","C":"Отказ TCP происходит до аутентификации PostgreSQL.","D":"По условию соединение выполнялось к IP, а отказ получен на TCP-этапе."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'TCP-подключение к базе истекло по таймауту. Какой вывод обоснован без дополнительных проверок?', '{"A":"Соединение не установилось за отведённое время","B":"Сервер базы гарантированно выключен целиком","C":"База уже приняла запрос и откатила транзакцию","D":"На сервере наверняка неверен пароль роли"}'::jsonb, 'A', 'Потеря пакетов, firewall с DROP, неверный маршрут и недоступный узел могут выглядеть одинаково для клиента.', '{"A":"Причину уточняют по пути, фильтрации, ответам сервера и нагрузке.","B":"Таймаут возможен и при работающем сервере, например из-за фильтрации.","C":"Таймаут установления TCP не означает, что запрос дошёл до базы.","D":"Для проверки пароля сначала нужно установить транспортное соединение."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'ping до сервера не отвечает, но HTTPS-запрос с этого клиента успешно получает страницу. Как это возможно?', '{"A":"HTTPS работает без какой-либо передачи IP-пакетов","B":"Успешный HTTP-ответ доказывает неисправность DNS","C":"ICMP и HTTPS обрабатываются по разным правилам","D":"ping проверяет пароль, а HTTPS — сетевую карту"}'::jsonb, 'C', 'Отсутствие ответа на ping не доказывает недоступность конкретной прикладной службы. Проверяют нужный протокол и порт.', '{"A":"HTTPS поверх TCP всё равно использует сетевой путь к серверу.","B":"Успех запроса по имени, наоборот, предполагает получение адреса каким-либо способом.","C":"ICMP может фильтроваться, хотя TCP-порт HTTPS доступен.","D":"ICMP echo не проверяет пароль учётной записи."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В ss TCP-соединение с базой имеет состояние ESTAB. Что этим подтверждено?', '{"A":"Последняя транзакция приложения уже зафиксирована","B":"TCP-соединение установлено","C":"Пользователь уже успешно прошёл аутентификацию БД","D":"Приложение успешно выполнило проверочный SELECT"}'::jsonb, 'B', 'Для проверки готовности базы нужен запрос, например SELECT 1, под подходящей ролью и с ограничением времени.', '{"A":"Состояние TCP не раскрывает состояние транзакции PostgreSQL.","B":"ESTAB описывает состояние транспорта, а не результат аутентификации или SQL.","C":"Протокольная аутентификация происходит после установки TCP.","D":"Факт выполнения запроса нужно проверять на уровне приложения или базы."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Два клиента одновременно соединяются с одним IP PostgreSQL на TCP-порт 5432. Как сервер различает обычные TCP-соединения?', '{"A":"По одному номеру серверного порта 5432","B":"По паре IP и порта каждого конца","C":"По имени базы до установки TCP-соединения","D":"По порядку записей об имени сервера в DNS"}'::jsonb, 'B', 'Клиент обычно использует временный исходный порт. Например, различие client1:41000 и client1:41001 позволяет двум соединениям идти к одному server:5432.', '{"A":"У обоих соединений серверный порт одинаков, этого недостаточно.","B":"В одном сетевом контексте TCP-соединение задаётся адресами и портами обеих сторон.","C":"Имя базы передаётся позже, внутри протокола PostgreSQL.","D":"Порядок DNS-ответов не идентифицирует установленное TCP-соединение."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'HTTPS по имени работает. При обращении к тому же серверу по IP клиент сообщает о несовпадении имени сертификата. Что проверить?', '{"A":"Соответствие имени обращения именам сертификата","B":"Не изменился ли MAC-адрес шлюза сервера","C":"Соответствие порта обращения записи DNS типа A","D":"Не нужно ли разрешить IP клиента в firewall"}'::jsonb, 'A', 'При диагностике сохраняют имя сервера для SNI и проверки сертификата. Выключать проверку TLS ради обхода ошибки не является исправлением.', '{"A":"Сертификат для DNS-имени не обязан быть действительным для буквального IP.","B":"MAC шлюза не задаёт имя, которое клиент проверяет в сертификате.","C":"A-запись не задаёт TCP-порт и не определяет допустимые имена сертификата.","D":"Проверка имени уже дошла до сертификата; firewall не добавляет IP в его имена."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'nginx вернул клиенту 504 Gateway Timeout. Какой вывод корректен?', '{"A":"Клиент не смог установить TCP к nginx","B":"PostgreSQL на этом сервере наверняка остановлен","C":"Имя nginx не удалось разрешить на клиенте","D":"Прокси не дождался ответа upstream в срок"}'::jsonb, 'D', 'За прокси могут быть приложение, база и внешние сервисы. Диагностику продолжают по цепочке, а не подменяют 504 единственной гипотезой.', '{"A":"Полученный HTTP-код предполагает, что до HTTP-сервера удалось дойти.","B":"Upstream может ждать по разным причинам; состояние базы отдельно не доказано.","C":"Клиент получил HTTP-ответ от прокси, значит этот этап уже пройден.","D":"Конкретную причину ищут в журналах прокси и upstream."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'nginx на хосте пересылает запросы на 127.0.0.1:3000. Приложение перенесли в отдельный контейнер без публикации порта, но upstream не изменили. Что проверить первым?', '{"A":"Нужно ли добавить ещё одну DNS-запись AAAA для сайта","B":"Как хост может достичь порта приложения в контейнере","C":"Применились ли публичные DNS-записи сайта у клиентов","D":"Разрешает ли внешний firewall входящий порт 3000"}'::jsonb, 'B', 'В зависимости от схемы используют опубликованный порт на хосте или доступный маршрут к контейнеру; проверяют фактическое прослушивание.', '{"A":"Проблема локального upstream не устраняется новой публичной AAAA-записью.","B":"Старый localhost upstream относится к хосту, а не к новому сетевому пространству.","C":"Клиент уже дошёл до nginx; изменение публичного DNS не делает localhost upstream адресом контейнера.","D":"Внешнее правило не перенаправляет соединение хоста на loopback в другое сетевое пространство."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В PostgreSQL 16 изменили listen_addresses с localhost на конкретный адрес сетевой карты. Достаточно ли pg_reload_conf() для применения этого параметра?', '{"A":"Нет, требуется перезагрузка операционной системы","B":"Да, перечитывание немедленно перепривяжет сокеты","C":"Да, если одновременно перечитать файл pg_hba.conf","D":"Нет, для него нужен перезапуск экземпляра"}'::jsonb, 'D', 'Перед изменением проверяют адреса, firewall и правила аутентификации. Запуск на адресе не означает автоматического разрешения входа любой роли.', '{"A":"Достаточен перезапуск нужного PostgreSQL; перезагрузка всего хоста не требуется.","B":"Смена адресов прослушивания не выполняется обычным reload PostgreSQL.","C":"Перечитывание правил входа не меняет контекст применения listen_addresses.","D":"listen_addresses относится к параметрам, применяемым при запуске сервера."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'psql на Linux вызван с -h 127.0.0.1. Какой тип записей pg_hba.conf относится к этому соединению?', '{"A":"host и его подходящие TCP-разновидности","B":"local, потому что клиент на той же машине","C":"Любая запись, где совпало имя интерфейса eth0","D":"replication независимо от выбранной базы"}'::jsonb, 'A', 'Соединение без -h обычно идёт через Unix-сокет, если параметры окружения и сервиса не задают иное. С -h 127.0.0.1 используется TCP.', '{"A":"Явный IPv4-адрес выбирает TCP, с учётом шифрования могут подойти hostssl или hostnossl.","B":"local означает Unix-domain socket, а не любое соединение с локального компьютера.","C":"Формат HBA не выбирает правило по имени сетевой карты.","D":"replication в поле database относится к определённым подключениям репликации."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'В pg_hba.conf первая подходящая запись требует парольную аутентификацию; вход по ней не удался. Ниже есть подходящая запись trust. Что произойдёт?', '{"A":"Клиент автоматически переключится на Unix-сокет","B":"Сервер откроет новый порт для повторного входа","C":"Подключение завершится отказом","D":"Сервер повторит вход по нижней записи trust"}'::jsonb, 'C', 'Порядок правил имеет значение. Правило выбирают по типу соединения, адресу, базе и роли, а затем применяют заданный метод.', '{"A":"Отказ по HBA не меняет транспорт уже установленного соединения.","B":"Порядок записей HBA не создаёт дополнительные слушатели.","C":"После выбора первой подходящей записи HBA не перебирает следующие при неуспешной аутентификации.","D":"В HBA нет такого fallback на следующую запись после отказа аутентификации."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Клиент базы имеет IPv4-адрес 192.0.2.25 без NAT. Какой CIDR в поле address pg_hba.conf ограничивает правило этим одним адресом?', '{"A":"192.0.0.0/16","B":"192.0.2.25/32","C":"192.0.2.0/24","D":"0.0.0.0/0"}'::jsonb, 'B', 'Сервер сопоставляет адрес, который видит у подключения. При NAT или прокси он может отличаться от собственного адреса клиентской машины.', '{"A":"Этот префикс ещё шире: он охватывает множество /24.","B":"Префикс /32 совпадает с одним IPv4-адресом.","C":"Этот префикс охватывает всю подсеть, а не один клиент.","D":"Это любой IPv4-адрес, а не заданный клиент."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'systemctl is-active postgresql возвращает active, но подключения к порту 5432 не работают. Что проверить дальше на Debian/Ubuntu?', '{"A":"Изменить HBA до проверки состояния кластера","B":"Сменить пароль роли до проверки слушателя","C":"Конкретный кластер и его сокеты","D":"Считать порт исправным по статусу общей службы"}'::jsonb, 'C', 'Используют pg_lsclusters, состояние postgresql@16-main и ss, затем проверяют соединение и SQL. Имя конкретной службы зависит от установленного кластера.', '{"A":"Правила входа не запустят остановленный экземпляр и не создадут его сокеты.","B":"При неработающем транспорте до проверки пароля дело ещё не дошло.","C":"Общая служба может быть active, даже когда нужный экземпляр остановлен.","D":"Агрегирующий статус не заменяет проверку нужного процесса и порта."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'По имени сервер получил IPv6-адрес и подключение не удалось. Явное подключение к его IPv4-адресу успешно. Как продолжить диагностику?', '{"A":"Сразу изменить пароль роли на сервере PostgreSQL","B":"Считать весь DNS неработоспособным из-за ошибки TCP","C":"Удалить IPv4-маршрут, чтобы клиент выбрал IPv6","D":"Отдельно проверить AAAA, IPv6-маршрут и слушатель"}'::jsonb, 'D', 'Проверяют все полученные адреса и реальный выбор клиента. Не подменяют такую диагностику отключением IPv6 во всей системе.', '{"A":"Различие семейств адресов нужно проверить до смены учётных данных.","B":"Разрешение имени могло успешно вернуть адрес с неисправным сетевым путём.","C":"Удаление рабочего пути не объясняет и не исправляет неисправный IPv6.","D":"У IPv4 и IPv6 могут различаться пути, фильтрация и адреса прослушивания."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Вы подключены по SSH к рабочему серверу. Какие команды читают состояние сети без её перенастройки?', '{"A":"ss -ltn","B":"ip route show","C":"ip route flush table main","D":"ip -br address"}'::jsonb, 'ABD', 'Перед исправлением собирают факты. Изменение маршрутов, ifdown и restart сети могут затронуть действующее удалённое подключение.', '{"A":"Показывает слушающие TCP-сокеты.","B":"Читает таблицу маршрутов.","C":"Удаляет маршруты из основной таблицы и может оборвать SSH.","D":"Показывает интерфейсы и адреса, не изменяя их."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '21.'), 'Администратор добавил IP командой ip address add, а затем перезагрузил сервер. Адрес исчез. Что следует проверить?', '{"A":"Сохранён ли адрес в конфигурации сетевого менеджера","B":"Добавлен ли IP в постоянный маршрут default","C":"Закреплён ли адрес настройкой слушателя службы","D":"Истёк ли TTL записи в DNS-кэше клиента"}'::jsonb, 'A', 'На машине нужно знать действующий инструмент: ifupdown, systemd-networkd, NetworkManager или генератор конфигурации. Файл одного инструмента не обязательно управляет другим.', '{"A":"Команда ip изменяет текущее состояние ядра, а не настройки следующей загрузки.","B":"Маршрут и локальный адрес — разные настройки: сохранение маршрута не назначает IP карте.","C":"Привязка слушателя сама не сохраняет адрес интерфейса на следующую загрузку.","D":"TTL DNS не управляет локальными постоянными настройками интерфейса."}'::jsonb;

DO $check$
DECLARE candidate record; matches integer;
BEGIN
    FOR candidate IN SELECT * FROM question_seed LOOP
        SELECT count(*) INTO matches FROM questions q
        WHERE regexp_replace(trim(q.question_text), '[[:space:]]+', ' ', 'g') =
              regexp_replace(trim(candidate.question_text), '[[:space:]]+', ' ', 'g');
        IF matches > 1 OR (matches = 1 AND NOT EXISTS (
            SELECT 1 FROM questions q WHERE q.question_text = candidate.question_text
              AND q.category_id = candidate.category_id AND q.options = candidate.options
              AND q.correct_answer = candidate.correct_answer AND q.explanation = candidate.explanation
              AND q.option_notes = candidate.option_notes
        )) THEN
            RAISE EXCEPTION 'Конфликт содержимого или повтор нового вопроса';
        END IF;
    END LOOP;
END
$check$;

INSERT INTO questions(category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM question_seed n
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
BEGIN
    IF (SELECT count(*) FROM questions q JOIN question_seed n ON q.question_text = n.question_text) <> 48 THEN
        RAISE EXCEPTION 'Неверное число вопросов после добавления';
    END IF;
END
$check$;

COMMIT;
